dfs(node, pattern, i):
    if i == size of pattern: return node is marked "$"
    ch = pattern[i]
    if ch is not ".":
        if ch not in node: return false   (a literal mismatch prunes the whole subtree)
        return dfs(node[ch], pattern, i + 1)
    for each key in node, skipping "$":   (wildcard: try every real child)
        if dfs(node[key], pattern, i + 1): return true
    return false
